import React, { useState, useEffect } from 'react';
import api from '../api';

function UserManagement() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'front_office_employee'
  });

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    setLoading(true);
    try {
      const data = await api.getAllUsers();
      setUsers(data);
    } catch (error) {
      console.error('Error loading users:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateUser = async (e) => {
    e.preventDefault();
    try {
      await api.createUser(formData);
      setFormData({
        username: '',
        password: '',
        name: '',
        role: 'front_office_employee'
      });
      setShowCreateForm(false);
      loadUsers();
      alert('User created successfully!');
    } catch (error) {
      console.error('Error creating user:', error);
      alert('Error creating user. Username may already exist.');
    }
  };

  const handleDeleteUser = async (userId, username) => {
    if (window.confirm(`Are you sure you want to delete user "${username}"? This cannot be undone.`)) {
      try {
        await api.deleteUser(userId);
        loadUsers();
        alert('User deleted successfully!');
      } catch (error) {
        console.error('Error deleting user:', error);
        alert('Error deleting user.');
      }
    }
  };

  const getRoleBadgeColor = (role) => {
    switch (role) {
      case 'grand_admin': return '#8e44ad';
      case 'front_office_admin': return '#3498db';
      case 'sales_admin': return '#e67e22';
      case 'manager': return '#16a085';
      case 'front_office_employee': return '#27ae60';
      case 'sales_employee': return '#f39c12';
      default: return '#95a5a6';
    }
  };

  const formatRole = (role) => {
    return role.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  if (loading) {
    return <div className="loading">Loading users...</div>;
  }

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>User Management</h1>
        <p>Create and manage user accounts</p>
      </div>

      <button 
        className="btn btn-primary" 
        onClick={() => setShowCreateForm(!showCreateForm)}
        style={{ marginBottom: '20px' }}
      >
        {showCreateForm ? 'Cancel' : '+ Create New User'}
      </button>

      {showCreateForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create New User</h3>
          <form onSubmit={handleCreateUser}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div className="form-group">
                <label>Username</label>
                <input
                  type="text"
                  className="form-control"
                  value={formData.username}
                  onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                  required
                />
              </div>
              <div className="form-group">
                <label>Password</label>
                <input
                  type="password"
                  className="form-control"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  required
                />
              </div>
              <div className="form-group">
                <label>Full Name</label>
                <input
                  type="text"
                  className="form-control"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
              </div>
              <div className="form-group">
                <label>Role</label>
                <select
                  className="form-control"
                  value={formData.role}
                  onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                >
                  <option value="grand_admin">Grand Admin</option>
                  <option value="front_office_admin">Front Office Admin</option>
                  <option value="front_office_employee">Front Office Employee</option>
                  <option value="sales_admin">Sales Admin</option>
                  <option value="sales_employee">Sales Employee</option>
                  <option value="manager">Manager</option>
                </select>
              </div>
            </div>
            <button type="submit" className="btn btn-success" style={{ marginTop: '10px' }}>
              Create User
            </button>
          </form>
        </div>
      )}

      <div className="task-section">
        <h3 style={{ marginBottom: '20px' }}>All Users ({users.length})</h3>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#34495e', color: 'white' }}>
              <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Username</th>
              <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Name</th>
              <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Role</th>
              <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Created</th>
              <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'center' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user.id}>
                <td style={{ border: '1px solid #ddd', padding: '12px' }}>{user.username}</td>
                <td style={{ border: '1px solid #ddd', padding: '12px' }}>{user.name}</td>
                <td style={{ border: '1px solid #ddd', padding: '12px' }}>
                  <span style={{
                    backgroundColor: getRoleBadgeColor(user.role),
                    color: 'white',
                    padding: '4px 12px',
                    borderRadius: '12px',
                    fontSize: '12px',
                    fontWeight: '600'
                  }}>
                    {formatRole(user.role)}
                  </span>
                </td>
                <td style={{ border: '1px solid #ddd', padding: '12px' }}>
                  {new Date(user.created_at).toLocaleDateString('en-US')}
                </td>
                <td style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'center' }}>
                  <button
                    className="btn"
                    onClick={() => handleDeleteUser(user.id, user.username)}
                    style={{ backgroundColor: '#e74c3c', color: 'white', padding: '6px 12px' }}
                    onMouseEnter={(e) => e.target.style.backgroundColor = '#c0392b'}
                    onMouseLeave={(e) => e.target.style.backgroundColor = '#e74c3c'}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default UserManagement;
